        /// <summary>查询指定协议/状态/方向下包名对应的包 ID。</summary>
        public static bool TryGetId(int protocol, PacketState state, PacketDirection direction, PacketName name, out int id)
            => ByName.TryGetValue((protocol, state, direction, name), out id);

        /// <summary>查询包 ID，不存在时抛 ProtocolException。</summary>
        public static int GetId(int protocol, PacketState state, PacketDirection direction, PacketName name)
            => ByName.TryGetValue((protocol, state, direction, name), out int id)
                ? id
                : throw new ProtocolException($"协议 {protocol} 不存在包 {state}/{direction}/{name}");

        /// <summary>由包 ID 反查包名（用于日志与分发）。</summary>
        public static bool TryGetName(int protocol, PacketState state, PacketDirection direction, int id, out PacketName name)
            => ById.TryGetValue((protocol, state, direction, id), out name);
    }
